package com.studybuddy.api.api;
import com.studybuddy.api.api.ApiDtos.*; import com.studybuddy.api.security.CurrentUser; import com.studybuddy.api.service.ModerationService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1")
public class AdminController { private final CurrentUser current; private final ModerationService moderation; public AdminController(CurrentUser current,ModerationService moderation){this.current=current;this.moderation=moderation;} @PostMapping("/reports") @ResponseStatus(HttpStatus.CREATED) public ReportResponse report(Authentication a,@Valid @RequestBody ReportRequest r){return moderation.report(current.require(a),r);} @GetMapping("/admin/reports") @PreAuthorize("hasRole('ADMIN')") public List<ReportResponse> reports(){return moderation.openReports();} @PostMapping("/admin/users/{id}/status") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void status(Authentication a,@PathVariable Long id,@RequestParam boolean active){moderation.deactivate(current.require(a),id,active);} @PostMapping("/admin/messages/{id}/remove") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(Authentication a,@PathVariable Long id){moderation.removeMessage(current.require(a),id);} }
